(TypeScript) Background refresher sketch:

const client = new RedwoodClient({ tokenProvider: DefaultTokenProvider.fromEnv() });
client.enableBackgroundRefresh({ windowSeconds: 120, maxRetries: 5 });

(Stream reauth pseudocode)
stream.on('message', (m) => { /* ... */ });
stream.on('error', async (err) => { if (err.status === 401) { await client.tokenProvider.refresh(); await client.stream.resume(); } });

(Python) context-managed refresher:
with RedwoodClient(token_provider=EnvTokenProvider()) as client:
    client.start_refresher(window_seconds=120)
    for chunk in client.stream_generate(...):
        handle(chunk)
